plugins {
    alias(libs.plugins.flightplanner.jvm.library)
}

// The aircraft silhouettes and the rule that picks one for an airframe. Pure JVM,
// like `:core:handoff`, so the phone and the watch draw the same outlines from
// one table, and the coverage tests run in milliseconds. `AircraftShapes.kt` is
// generated by `:tools:aircraftart`; see that module's Main.kt.

dependencies {
    api(projects.core.model)

    testImplementation(libs.kotlin.test)
    testImplementation(libs.kotest.assertions.core)
}

tasks.withType<Test>().configureEach {
    // The coverage test reads the fleet the app actually seeds, not a copy of it.
    val seed = rootProject.layout.projectDirectory.file("app/src/main/assets/seed/aircrafts.csv").asFile
    inputs.file(seed)
    systemProperty("flightplanner.seedCsv", seed.absolutePath)
}
